import type {
  Character,
  RejectedRelation,
  RejectedRelationVia,
} from "../models/character";
import { createNameResolver, type NameResolution } from "./characterNameResolve";

/**
 * 退けた関係（作者の裁定、2026-09-23「退けた関係を記録する」）。
 *
 * 0.83.2（B3）で関係を直せるようになったが、**外部AIの提案で直しても、
 * その人物が `autoGenerated: true` のままだと、次の抽出が誤りを積み戻す**。
 * 抽出のマージは関係の言葉が違えば両方残す（`dedupeRelations`）ので、
 * 「ターナ=母」に直したところへ「ターナ=父の娘」がまた足される。
 *
 * そこで、**直して消えた関係を人物ごとに記録し、抽出と外部AIの提案が
 * 同じものを足そうとしたら足さない**。記録するのは作者の操作だけ
 * （設定資料パネルで消す・言葉を変える／承認の画面で、消える関係を含む
 * 更新案を採る）。**作者が同じ関係を手で入れ直したら、記録から外す**
 * ——作者の意思が勝つ。
 *
 * ## 一致の判定
 *
 * - **相手**：相関図と同じ `createNameResolver` で人物へ引き当て、同じ人物なら
 *   同じ相手とみなす（「ターナ」と「ターナ・ルー」）。資料に居ない・
 *   決めきれない相手は、**名前そのもの**を比べる
 * - **関係の言葉**：前後の空白を落とし、全角半角をそろえて（NFKC）完全一致
 * - **似ているだけのものは一致としない**（「父の娘」と「父の娘さん」「娘」は別）。
 *   退けた記録は、足すはずの関係を黙って止める強い仕組みなので、広く当てると
 *   別の正しい関係まで止める。止め損ねたものは承認の画面で作者に見えるが、
 *   止めすぎたものは誰にも見えない——**迷ったら止めない**側に倒す
 *
 * VS Code API に依存しない（MCP の束の `novel.propose` からも使う）。
 */

type Relation = { name: string; relation: string };
type Resolve = (name: string) => NameResolution;

/**
 * 比べるための形。前後の空白を落とし、全角半角をそろえる。
 *
 * NFKC を使うのは、全角英数・半角カナ・全角空白をまとめてそろえられるから。
 * 中の空白は詰めない（「父の 娘」は作者が別に書いた言葉として扱う）。
 */
export function foldRelationText(text: string): string {
  return text.normalize("NFKC").trim();
}

/** 相手を指す鍵。人物に引き当てられればそのid、だめなら名前そのもの */
function targetKey(resolve: Resolve, name: string): string {
  const trimmed = name.trim();
  const direct = resolve(trimmed);
  if (direct.id) return `id:${direct.id}`;
  const folded = foldRelationText(trimmed);
  if (folded !== trimmed) {
    const again = resolve(folded);
    if (again.id) return `id:${again.id}`;
  }
  return `name:${folded}`;
}

/**
 * 関係1件の鍵。区切りにNULを使うのは、名前にも関係にも現れない文字だから
 * （ソースには生のNULを置かずエスケープで書く）
 */
function relationKey(resolve: Resolve, name: string, relation: string): string {
  return `${targetKey(resolve, name)}\u0000${foldRelationText(relation)}`;
}

/**
 * 関係が、退けた記録のどれかと一致するかを引く道具。
 * 一致した記録の位置を返す（無ければ -1）。抽出の報告で、同じ記録に
 * 何話ぶん当たっても1件に数えるのに使う
 */
export function createRejectedRelationMatcher(
  characters: readonly Character[],
  rejected: ReadonlyArray<Pick<RejectedRelation, "target" | "relation">>
): (name: string, relation: string) => number {
  if (rejected.length === 0) return () => -1;
  const resolve = createNameResolver(characters);
  const keys = new Map<string, number>();
  rejected.forEach((entry, index) => {
    const key = relationKey(resolve, entry.target, entry.relation);
    if (!keys.has(key)) keys.set(key, index);
  });
  return (name, relation) => {
    // AIの出力は形が崩れていることがある。空のものは何にも当てない
    if (!name?.trim() || !relation?.trim()) return -1;
    return keys.get(relationKey(resolve, name, relation)) ?? -1;
  };
}

/** 1件どうしを比べる（画面やテストで使う） */
export function isSameRelation(
  characters: readonly Character[],
  relation: Relation,
  rejected: Pick<RejectedRelation, "target" | "relation">
): boolean {
  return (
    createRejectedRelationMatcher(characters, [rejected])(
      relation.name,
      relation.relation
    ) >= 0
  );
}

/**
 * 退けた関係を外す。**外したものも返す**（黙って捨てない。報告に出す）。
 * 残りの並びは保つ。
 */
export function withoutRejectedRelations(
  relations: readonly Relation[],
  rejected: readonly RejectedRelation[],
  characters: readonly Character[]
): { kept: Relation[]; skipped: Relation[] } {
  const matches = createRejectedRelationMatcher(characters, rejected);
  const kept: Relation[] = [];
  const skipped: Relation[] = [];
  for (const relation of relations) {
    if (matches(relation.name, relation.relation) >= 0) skipped.push(relation);
    else kept.push(relation);
  }
  return { kept, skipped };
}

/**
 * 前後を比べ、**消えた関係**を退けた記録へ足した一覧を返す。
 *
 * - 消えたかどうかも同じ一致の判定で見る（空白や全角半角を直しただけ、
 *   「ターナ」を「ターナ・ルー」と書き直しただけのものは、消えたことにしない）
 * - 既に退けてある関係は二重に記録しない
 * - `reinstate` が真なら、**後ろに残っている関係と一致する記録を外す**。
 *   設定資料パネルの保存で使う——作者が関係欄に手で入れ直したものである
 *   （作者の意思が勝つ）。承認の画面では使わない（そちらは更新案の中身で、
 *   作者の手書きではない。退けた関係は `settlePendingRelations` で先に外してある）
 */
export function recordRemovedRelations(input: {
  before: readonly Relation[];
  after: readonly Relation[];
  rejected: readonly RejectedRelation[];
  characters: readonly Character[];
  via: RejectedRelationVia;
  now: string;
  reinstate?: boolean;
}): RejectedRelation[] {
  const resolve = createNameResolver(input.characters);
  const key = (name: string, relation: string): string =>
    relationKey(resolve, name, relation);

  const afterKeys = new Set(
    input.after.map((relation) => key(relation.name, relation.relation))
  );
  const next = input.reinstate
    ? input.rejected.filter(
        (entry) => !afterKeys.has(key(entry.target, entry.relation))
      )
    : [...input.rejected];
  const known = new Set(next.map((entry) => key(entry.target, entry.relation)));

  for (const relation of input.before) {
    const name = relation.name.trim();
    const text = relation.relation.trim();
    if (!name || !text) continue;
    const relationId = key(name, text);
    if (afterKeys.has(relationId) || known.has(relationId)) continue;
    known.add(relationId);
    next.push({ target: name, relation: text, rejectedAt: input.now, via: input.via });
  }
  return next;
}

/**
 * 承認待ちの更新案を、いまの台帳に合わせて整える（承認の画面が組む前に通す）。
 *
 * 更新案は**積んだ時点の写し**である。積んだあとに作者が退けた関係は、
 * 写しの中では「足される関係」に見え、そのまま承認すると戻ってしまう
 * （未反映の更新案が何十件も溜まるのは珍しくない）。
 *
 * - **いま台帳に無く、退けた記録に一致する関係**だけを更新案から外し、
 *   外したものを返す（承認の画面の説明に件数を出す）
 * - いま台帳にある関係は、退けた記録と重なっても外さない（外すと承認で
 *   「消える」ことになる。作者の手でしか消さない）
 * - **退けた記録そのものは、台帳の側を正とする。** 写しの古い記録で
 *   巻き戻さない（AIは書かない欄。規則2）
 */
export function settlePendingRelations(
  current: Character,
  pending: Character,
  characters: readonly Character[]
): { character: Character; skipped: Relation[] } {
  const rejected = current.rejectedRelations;
  if (rejected.length === 0) {
    return {
      character: { ...pending, rejectedRelations: [] },
      skipped: [],
    };
  }
  const resolve = createNameResolver(characters);
  const currentKeys = new Set(
    current.relations.map((relation) =>
      relationKey(resolve, relation.name, relation.relation)
    )
  );
  const matches = createRejectedRelationMatcher(characters, rejected);
  const relations: Relation[] = [];
  const skipped: Relation[] = [];
  for (const relation of pending.relations) {
    const inLedger = currentKeys.has(
      relationKey(resolve, relation.name, relation.relation)
    );
    if (!inLedger && matches(relation.name, relation.relation) >= 0) {
      skipped.push(relation);
      continue;
    }
    relations.push(relation);
  }
  return {
    character: { ...pending, relations, rejectedRelations: [...rejected] },
    skipped,
  };
}

/**
 * 退けた記録から1件外す（設定資料パネルの「退けた記録から外す」）。
 *
 * **関係そのものは戻さない。** 外すのは「次の抽出で足してよい」と
 * 許すことで、戻すかどうかは作者が関係欄で決める。
 * 指すのは書かれた文字どおり（画面は記録を1件ずつ出しているので、
 * 一致の判定で広く当てると、別の記録まで外れる）。
 */
export function forgetRejectedRelation(
  character: Character,
  target: string,
  relation: string
): Character {
  let removed = false;
  const rejectedRelations = character.rejectedRelations.filter((entry) => {
    if (removed) return true;
    if (entry.target === target && entry.relation === relation) {
      removed = true;
      return false;
    }
    return true;
  });
  return removed ? { ...character, rejectedRelations } : character;
}

/**
 * 設定資料パネルに並べる1件の添え書き（いつ・どう退けたか）。
 * 日付は年月日だけ（時刻まで出しても作者の判断には要らない）
 */
export function describeRejectedRelation(entry: RejectedRelation): string {
  const date = entry.rejectedAt.slice(0, 10);
  const how = rejectedRelationViaLabel(entry.via);
  return date ? `${date}に${how}退けました` : `${how}退けました`;
}

/** 退けた経緯の短い言い方。画面に出す文言はここだけが持つ */
export function rejectedRelationViaLabel(via: RejectedRelationVia): string {
  switch (via) {
    case "panel":
      return "設定資料パネルで";
    case "extraction":
      return "抽出の更新案を承認して";
    case "external":
      return "外部AIの提案を承認して";
    case "plot":
      return "プロットからの更新案を承認して";
    case "chat":
      return "相談からの更新案を承認して";
  }
}
